<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php'; admin_required();
if ($_SERVER['REQUEST_METHOD'] !== 'POST') { header('Location: index.php'); exit; }
verify_csrf(); $connection=db(); $orderId=filter_input(INPUT_POST,'order_id',FILTER_VALIDATE_INT); $action=$_POST['action']??'';
if(!$orderId){flash('error','Invalid order.');header('Location: index.php');exit;}
$connection->begin_transaction();
try {
    $statement=$connection->prepare('SELECT * FROM orders WHERE id=? FOR UPDATE');$statement->bind_param('i',$orderId);$statement->execute();$order=$statement->get_result()->fetch_assoc();if(!$order)throw new RuntimeException('Order not found.');
    if($action==='status'){$status=$_POST['status']??'';if(!in_array($status,['new','confirmed','processing','ready','completed','cancelled'],true))throw new RuntimeException('Invalid status.');$itemsStatement=$connection->prepare('SELECT * FROM order_items WHERE order_id=?');$itemsStatement->bind_param('i',$orderId);$itemsStatement->execute();$items=$itemsStatement->get_result()->fetch_all(MYSQLI_ASSOC);
        if($status!=='cancelled'&&$order['stock_deducted_at']===null){foreach($items as $item){$statement=$connection->prepare('SELECT stock_quantity FROM products WHERE id=? FOR UPDATE');$statement->bind_param('i',$item['product_id']);$statement->execute();$product=$statement->get_result()->fetch_assoc();if(!$product||(int)$product['stock_quantity']<(int)$item['quantity'])throw new RuntimeException('Insufficient stock for '.$item['product_name'].'.');}$now=date('Y-m-d H:i:s');foreach($items as $item){$statement=$connection->prepare('UPDATE products SET stock_quantity=stock_quantity-? WHERE id=?');$statement->bind_param('ii',$item['quantity'],$item['product_id']);$statement->execute();$note='Order '.$order['order_number'].' confirmed';$statement=$connection->prepare("INSERT INTO stock_movements (product_id,order_id,movement_type,quantity,notes) VALUES (?,?,'out',?,?)");$statement->bind_param('iiis',$item['product_id'],$orderId,$item['quantity'],$note);$statement->execute();}$statement=$connection->prepare('UPDATE orders SET stock_deducted_at=? WHERE id=?');$statement->bind_param('si',$now,$orderId);$statement->execute();}
        if($status==='cancelled'&&$order['stock_deducted_at']!==null){foreach($items as $item){$statement=$connection->prepare('UPDATE products SET stock_quantity=stock_quantity+? WHERE id=?');$statement->bind_param('ii',$item['quantity'],$item['product_id']);$statement->execute();$note='Order '.$order['order_number'].' cancelled';$statement=$connection->prepare("INSERT INTO stock_movements (product_id,order_id,movement_type,quantity,notes) VALUES (?,?,'restored',?,?)");$statement->bind_param('iiis',$item['product_id'],$orderId,$item['quantity'],$note);$statement->execute();}$statement=$connection->prepare('UPDATE orders SET stock_deducted_at=NULL WHERE id=?');$statement->bind_param('i',$orderId);$statement->execute();}
        $statement=$connection->prepare('UPDATE orders SET status=? WHERE id=?');$statement->bind_param('si',$status,$orderId);$statement->execute();flash('success','Order status updated and inventory reconciled.');
    } elseif($action==='payment') {$paymentStatus=$_POST['payment_status']??'';if(!in_array($paymentStatus,['pending','paid','failed','refunded'],true))throw new RuntimeException('Invalid payment status.');$statement=$connection->prepare('UPDATE payments SET payment_status=?,confirmed_by=?,confirmed_at=NOW() WHERE order_id=?');$statement->bind_param('sii',$paymentStatus,$_SESSION['admin_id'],$orderId);$statement->execute();$statement=$connection->prepare('UPDATE orders SET payment_status=? WHERE id=?');$statement->bind_param('si',$paymentStatus,$orderId);$statement->execute();flash('success','Payment status updated.');}else throw new RuntimeException('Invalid action.');
    $connection->commit();
}catch(Throwable $exception){$connection->rollback();error_log('Sammy Tech order update: '.$exception->getMessage());flash('error',$exception->getMessage());}
header('Location: index.php');exit;
